def period_from_year(year):
    if year < 1400: return "Ancient / Medieval"
    elif year < 1500: return "Early Renaissance"
    elif year < 1600: return "High Renaissance / Mannerism"
    elif year < 1700: return "Baroque"
    elif year < 1800: return "Rococo / Neoclassicism"
    elif year < 1850: return "Romanticism"
    elif year < 1900: return "Realism / Impressionism"
    elif year < 1945: return "Modernism"
    elif year < 1980: return "Post-War / Contemporary"
    else: return "Contemporary"

