def make_entry(idx, raw):
    if len(raw) == 12:
        title, artist, year, medium, movement, style, subject, colors, museum, desc, hist, gender = raw
        nationality = "Unknown"
    else:
        title, artist, year, medium, movement, style, subject, colors, museum, desc, hist, gender, nationality = raw[:13]

    period = period_from_year(year)
    tags = list(dict.fromkeys(
        [s.lower() for s in style[:4]] +
        [s.lower() for s in subject[:3]] +
        [movement.split("/")[0].strip().lower(), period.lower().split(" ")[0]]
    ))[:12]

    return {
        "id": idx,
        "title": title,
        "artist": artist,
        "year": year,
        "medium": medium,
        "movement": movement,
        "style": style,
        "subject": subject,
        "color_palette": colors if isinstance(colors, list) else [colors],
        "museum": museum,
        "description": desc,
        "historical_significance": hist,
        "artist_gender": gender,
        "artist_nationality": nationality,
        "period": period,
        "tags": tags,
    }

def main():
    with open(DATA_PATH, "r", encoding="utf-8") as f:
        existing = json.load(f)

    start_id = max(a["id"] for a in existing) + 1
    new_entries = []
    for i, raw in enumerate(BATCH2):
        try:
            entry = make_entry(start_id + i, raw)
            new_entries.append(entry)
        except Exception as e:
            print(f"  Skip {i} ({raw[0] if raw else '?'}): {e}")

    merged = existing + new_entries
    with open(DATA_PATH, "w", encoding="utf-8") as f:
        json.dump(merged, f, ensure_ascii=False, indent=2)

    print(f"Done. {len(existing)} existing + {len(new_entries)} new = {len(merged)} total.")

if __name__ == "__main__":
    main()
